/**
 * A chart drawn by `chart.ts`, shown on the paper it was laid out for.
 *
 * The palette is chosen against white — the comment in `chart.ts` says why it
 * cannot follow the app theme — so a chart gets a white card rather than the
 * app's own surface. One component holds that decision and the sizing, so the
 * conversation and the spend panel cannot drift apart about it.
 *
 * The markup is generated by this app, never by the model: `chartSvg` escapes
 * every label, and `chart.check.ts` asserts a hostile one cannot become markup.
 */
export function ChartImage({
  svg,
  className = "",
}: {
  /** The `svg` field of a successful `chartSvg` result. */
  svg: string;
  className?: string;
}) {
  return (
    <div
      className={`overflow-hidden rounded-lg border border-white/10 bg-white p-2 [&_svg]:h-auto [&_svg]:w-full ${className}`}
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}
